// Regenerates src/sites/index.ts from the site files (static imports keep the bundle resolvable by Metro).
import { readdirSync, writeFileSync } from "node:fs";

const dir = new URL("../src/sites/", import.meta.url);
const files = readdirSync(dir).filter((f) => f.endsWith(".ts") && f !== "index.ts").sort();
const ident = (f: string) => "s_" + f.replace(/\.ts$/, "").replace(/[^a-zA-Z0-9]/g, "_");
const lines = [
  "// Generated by scripts/registry.ts — do not edit.",
  'import type { Scraper } from "../scraper.ts";',
  ...files.map((f) => `import * as ${ident(f)} from "./${f}";`),
  "",
  "export const SITES: { hosts: string[]; scraper: typeof Scraper }[] = [",
  ...files.map((f) => `  { hosts: ${ident(f)}.hosts, scraper: ${ident(f)}.default },`),
  "];",
  "",
];
writeFileSync(new URL("index.ts", dir), lines.join("\n"));
console.log(`${files.length} sites`);
